package com.billing.service;
import com.billing.dto.BackupPayload; import com.billing.entity.*; import com.billing.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class BackupService {
 private final ProductRepository products; private final SettingsRepository settings;
 public BackupService(ProductRepository products,SettingsRepository settings){this.products=products;this.settings=settings;}
 public BackupPayload create(){List<BackupPayload.ProductBackup> productData=products.findByActiveTrue().stream().map(p->new BackupPayload.ProductBackup(p.getName(),p.getCategory(),p.getBarcode(),p.getPurchasePrice(),p.getSellingPrice(),p.getGstPercentage(),p.getHsnCode(),p.getQuantity(),p.getMinimumQuantity())).toList();Settings s=settings.findFirstByOrderByIdAsc().orElse(null);BackupPayload.SettingsBackup set=s==null?null:new BackupPayload.SettingsBackup(s.getCompanyName(),s.getCompanyAddress(),s.getCompanyPhone(),s.getCompanyEmail(),s.getGstNumber(),s.getInvoiceLogoUrl(),s.getInvoiceSize(),s.isDarkMode(),s.getPrinterSettings());return new BackupPayload(java.time.LocalDateTime.now().toString(),productData,set);}
 @Transactional public int restore(BackupPayload backup){if(backup==null||backup.products()==null)throw new IllegalArgumentException("Invalid backup file");for(var b:backup.products()){Product p=products.findByBarcode(b.barcode()).orElseGet(Product::new);p.setName(b.name());p.setCategory(b.category());p.setBarcode(b.barcode());p.setPurchasePrice(b.purchasePrice());p.setSellingPrice(b.sellingPrice());p.setGstPercentage(b.gstPercentage());p.setHsnCode(b.hsnCode());p.setQuantity(b.quantity());p.setMinimumQuantity(b.minimumQuantity());p.setActive(true);products.save(p);}if(backup.settings()!=null){var b=backup.settings();Settings s=settings.findFirstByOrderByIdAsc().orElseGet(Settings::new);s.setCompanyName(b.companyName());s.setCompanyAddress(b.companyAddress());s.setCompanyPhone(b.companyPhone());s.setCompanyEmail(b.companyEmail());s.setGstNumber(b.gstNumber());s.setInvoiceLogoUrl(b.invoiceLogoUrl());s.setInvoiceSize(b.invoiceSize());s.setDarkMode(Boolean.TRUE.equals(b.darkMode()));s.setPrinterSettings(b.printerSettings());settings.save(s);}return backup.products().size();}
}
